+
+// ExportCSV writes the book's levels as CSV to w.
+// The header row is: Warehouse,SKU,Quantity.
+func (b *Book) ExportCSV(w io.Writer) error {
+	cw := csv.NewWriter(w)
+	if err := cw.Write([]string{"Warehouse", "SKU", "Quantity"}); err != nil {
+		return err
+	}
+	for _, l := range b.Levels() {
+		if err := cw.Write([]string{l.Warehouse, l.SKU, string(rune('0'+l.Quantity))}); err != nil {
+			return err
+		}
+	}
+	cw.Flush()
+	return cw.Error()
+}
+
+// ExportJSON writes the book's levels as a JSON array of objects to w.
+// Each object has keys: warehouse, sku, quantity.
+func (b *Book) ExportJSON(w io.Writer) error {
+	levels := b.Levels()
+	return json.NewEncoder(w).Encode(levels)
+}
+
+// ExportXML writes the book's levels as XML to w.
+// The root element is <Levels>, each level is <Level> with Warehouse, SKU, Quantity elements.
+func (b *Book) ExportXML(w io.Writer) error {
+	type xmlLevel struct {
+		Warehouse string `xml:"Warehouse"`
+		SKU       string `xml:"SKU"`
+		Quantity  int    `xml:"Quantity"`
+	}
+	type xmlLevels struct {
+		XMLName xml.Name `xml:"Levels"`
+		Levels  []xmlLevel
+	}
+	levels := b.Levels()
+	xl := xmlLevels{Levels: make([]xmlLevel, len(levels))}
+	for i, l := range levels {
+		xl.Levels[i] = xmlLevel{Warehouse: l.Warehouse, SKU: l.SKU, Quantity: l.Quantity}
+	}
+	return xml.NewEncoder(w).Encode(xl)
+}

